def translate(text):
 text=text.replace('®','®').replace('™','™')
 for phrase,ru in sorted(PHRASES.items(),key=lambda pair:-len(pair[0])):text=re.sub(r'(?<![A-Za-z])'+re.escape(phrase)+r'(?![A-Za-z])',lambda _:ru,text)
 text=re.sub(r'[A-Za-z]+(?:-[A-Za-z]+)*',lambda m:WORDS.get(m[0],m[0]),text)
 text=re.sub(r'\s+',' ',text).strip(' ,;');return text
